mapper.select:
select model_id
from aircas_model
where base_model_id = #{baseModelId}

select am.model_id, am.model_id, am.base_model_id, abm.base_model_name, am.model_name, am.pretrain_checkpoint, am.version, am.model_type, am.data_type, am.resource, am.domain, am.support_options, am.license, am.download_source, am.catalogue, am.environment, am.config, am.train_config, am.description, am.create_by, am.update_by, am.create_time, am.update_time,abm.base_model_name from aircas_model am left join aircas_base_model abm on am.base_model_id = abm.base_model_id
am.del_flag = '0'
AND am.model_name LIKE #{modelNameLike}
AND am.model_id = #{query.model_id}
AND bd.model_type = #{query.modelType}
AND bd.base_model_id = #{query.baseModelId}
ORDER BY am.create_time DESC,am.update_time DESC

mapper.insert:
insert into aircas_model
( model_id, base_model_id, model_name
, pretrain_checkpoint, version, model_type,data_type
, resource, domain, support_options, license
, download_source, catalogue, environment
, config, train_config, description
, create_by, update_by, create_time
, update_time, del_flag)
values ( #{modelId,jdbcType=BIGINT}, #{baseModelId,jdbcType=BIGINT}, #{modelName,jdbcType=VARCHAR}
	   , #{pretrainCheckpoint,jdbcType=VARCHAR}, #{version,jdbcType=VARCHAR}, #{modelType,jdbcType=VARCHAR},#{dataType,jdbcType=VARCHAR}
	   , #{resource,jdbcType=VARCHAR}, #{domain,jdbcType=VARCHAR}, #{supportOptions,jdbcType=VARCHAR}
	   , #{license,jdbcType=VARCHAR}
	   , #{downloadSource,jdbcType=VARCHAR}, #{catalogue,jdbcType=VARCHAR}, #{environment,jdbcType=VARCHAR}
	   , #{config,jdbcType=VARCHAR}, #{trainConfig,jdbcType=VARCHAR}, #{description,jdbcType=VARCHAR}
	   , #{createBy,jdbcType=VARCHAR}, #{updateBy,jdbcType=VARCHAR}, #{createTime,jdbcType=TIMESTAMP}
	   , #{updateTime,jdbcType=TIMESTAMP}, #{delFlag,jdbcType=CHAR})
